from fractions import Fraction as F
import json
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
tests='TUVW'; modes='ABCD'; costs=dict(zip(tests,map(F,['1.8','1.5','1.2','0.8'])))
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def stop(s):
    w=sum(rows[i][1] for i in s)
    return min((sum(F(rows[i][1],w)*loss[a][modes.index(rows[i][0])] for i in s),modes[a]) for a in range(4))
def solve(s,available,budget):
    best=stop(s)
    if budget:
        for t in available:
            candidate=(buy(s,available,budget,t),t)
            if candidate<best: best=candidate
    return best
def buy(s,available,budget,t):
    w=sum(rows[i][1] for i in s)
    value=costs[t]
    for b in (0,1):
        sub=tuple(i for i in s if rows[i][2][tests.index(t)]==b)
        if sub:
            value+=F(sum(rows[i][1] for i in sub),w)*solve(sub,available.replace(t,''),budget-1)[0]
    return value
s=tuple(range(8))
vals={'STOP':float(stop(s)[0])}
vals.update({t:float(buy(s,tests,2,t)) for t in tests})
v,a=solve(s,tests,2)
nxt={}
if a in tests:
    for b in (0,1):
        sub=tuple(i for i in s if rows[i][2][tests.index(a)]==b)
        nxt[str(b)]=solve(sub,tests.replace(a,''),1)[1] if sub else 'IMPOSSIBLE'
artifact={'first':a,'first_losses':vals,'next':nxt}
payload=json.dumps(artifact)
recovered=json.loads(payload)
assert set(recovered)=={'first','first_losses','next'}
assert set(recovered['first_losses'])=={'STOP','T','U','V','W'}
# Independent exhaustive one-step continuation comparison on each possible first-test branch.
for t in tests:
    total=costs[t]
    for b in (0,1):
        sub=[i for i in s if rows[i][2][tests.index(t)]==b]
        if not sub: continue
        w=sum(rows[i][1] for i in sub)
        options=[stop(sub)[0]]
        for u in tests.replace(t,''):
            z=costs[u]
            for c in (0,1):
                leaf=[i for i in sub if rows[i][2][tests.index(u)]==c]
                if leaf: z+=F(sum(rows[i][1] for i in leaf),w)*stop(leaf)[0]
            options.append(z)
        total+=F(w,54)*min(options)
    assert abs(float(total)-recovered['first_losses'][t])<1e-10
print(payload)
print('Verified total weight:',sum(r[1] for r in rows))

