from fractions import Fraction as F
import json
# A duplicate display of the same stored W value is not new evidence.
rows=[('A',3,(0,0,0)),('B',5,(0,0,1)),('D',5,(0,0,1))]
modes='ABCD'; tests='TUV'; costs={'T':F('1.8'),'U':F('1.5'),'V':F('7.2')}
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def repair_values(s):
    weight=sum(r[1] for r in s)
    return {a:sum(F(r[1],weight)*loss[modes.index(a)][modes.index(r[0])] for r in s) for a in modes}
posterior={m:float(F(sum(r[1] for r in rows if r[0]==m),13)) for m in modes}
values=repair_values(rows)
branches={}
for t in tests:
    value=costs[t]; branches[t]={}
    for b in (0,1):
        sub=[r for r in rows if r[2][tests.index(t)]==b]
        if not sub:
            branches[t][str(b)]='IMPOSSIBLE'; continue
        rv=repair_values(sub)
        a=min(rv,key=rv.get)
        branches[t][str(b)]=a
        value+=F(sum(r[1] for r in sub),13)*rv[a]
    values[t]=value
a=min(values,key=values.get)
artifact={'posterior':posterior,'remaining_losses':{k:float(v) for k,v in values.items()},'action':a,'repair_after':branches[a] if a in tests else {}}
payload=json.dumps(artifact)
r=json.loads(payload)
assert set(r['posterior'])==set(modes) and abs(sum(r['posterior'].values())-1)<1e-12
assert set(r['remaining_losses'])==set('ABCDTUV')
# Direct weighted totals: A=135, B=106, C=198, D=109; V continuation=40/13.
for k,total in zip(modes,[135,106,198,109]):
    assert abs(r['remaining_losses'][k]-total/13)<1e-12
assert abs(r['remaining_losses']['V']-(7.2+40/13))<1e-12
assert r['action']=='B' and r['repair_after']=={}
print(payload)

